using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        int i = 0;
        int len = values.Length;
        ref float start = ref MemoryMarshal.GetReference(values);

        // SIMD path: two accumulators to hide multiply latency
        if (Vector256.IsHardwareAccelerated && len >= Vector256<float>.Count * 2)
        {
            var v0 = Vector256<float>.One;
            var v1 = Vector256<float>.One;
            int lastBlock = len - Vector256<float>.Count * 2;

            while (i <= lastBlock)
            {
                v0 *= Vector256.LoadUnsafe(ref start, (nuint)i);
                v1 *= Vector256.LoadUnsafe(ref start, (nuint)(i + Vector256<float>.Count));
                i += Vector256<float>.Count * 2;
            }

            v0 *= v1;

            if (i + Vector256<float>.Count <= len)
            {
                v0 *= Vector256.LoadUnsafe(ref start, (nuint)i);
                i += Vector256<float>.Count;
            }

            // Horizontal product: fold 256-bit → scalar
            var lo = v0.GetLower();
            var hi = v0.GetUpper();
            var combined = lo * hi;
            float product = combined[0] * combined[1] * combined[2] * combined[3];

            for (; i < len; i++)
                product *= Unsafe.Add(ref start, i);

            return product;
        }

        // Scalar fallback: 4 independent accumulators to exploit ILP
        float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
        int last4 = len - 3;
        for (; i < last4; i += 4)
        {
            p0 *= Unsafe.Add(ref start, i);
            p1 *= Unsafe.Add(ref start, i + 1);
            p2 *= Unsafe.Add(ref start, i + 2);
            p3 *= Unsafe.Add(ref start, i + 3);
        }

        p0 = (p0 * p1) * (p2 * p3);
        for (; i < len; i++)
            p0 *= Unsafe.Add(ref start, i);

        return p0;
    }
}

